package org.zhixiaoce.aperture;
import android.app.*;import android.os.*;import android.view.*;import android.webkit.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
/** Local album settings. Only exact bundled UI actions can mutate the private gallery. */
public final class GalleryActivity extends Activity {
    private WebView web;private GalleryStore store;private GalleryUpload upload;private AlertDialog notice;private boolean closed;
    public void onCreate(Bundle saved){super.onCreate(saved);getWindow().getDecorView().setSystemUiVisibility(5894);store=new GalleryStore(this);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setTextZoom(100);s.setUseWideViewPort(false);setContentView(web);
        web.setWebViewClient(new WebViewClient(){
            public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){WebResourceResponse gallery=store.read(r);if(gallery!=null)return gallery;Uri u=r.getUrl();String f=LobbyAssets.file(u.getScheme(),u.getHost(),u.getPort(),u.getPath());if("GET".equals(r.getMethod())&&f!=null&&u.getQuery()==null&&u.getFragment()==null&&u.getUserInfo()==null)try{return new WebResourceResponse(LobbyAssets.mime(f),"UTF-8",200,"OK",Collections.singletonMap("Cache-Control","no-store"),getAssets().open(f));}catch(IOException ignored){}return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
            public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(!r.isForMainFrame()||!"aperture".equals(u.getScheme())||!"gallery".equals(u.getHost())||u.getQuery()!=null||u.getFragment()!=null||u.getUserInfo()!=null)return true;String p=u.getPath();if("/back".equals(p)){finish();return true;}if("/upload".equals(p)){begin();return true;}if("/close-upload".equals(p)){stopUpload();refresh();return true;}
                if(p!=null&&p.matches("/delete/[a-f0-9]{32}")){if(notice!=null&&notice.isShowing())return true;String id=p.substring(8);notice=new AlertDialog.Builder(GalleryActivity.this).setTitle("删除这张照片？").setMessage("从电视相册中删除，手机原图不受影响。").setNegativeButton("保留",null).setPositiveButton("删除",(d,v)->{try{store.delete(id);refresh();}catch(Exception e){error("删除失败，请重试");}}).create();notice.show();notice.getButton(-2).requestFocus();return true;}
                if(p!=null&&p.matches("/set/(template/(fade|drift|diptych)|seconds/(8|12|20))")){String[] bits=p.split("/");try{store.option(bits[2],bits[3]);refresh();}catch(Exception e){error("设置未能保存");}}return true;}
        });web.loadUrl("https://"+LobbyAssets.HOST+"/assets/gallery.html");web.requestFocus();
    }
    private void refresh(){if(!closed)web.evaluateJavascript("window.KaishiGallerySettings&&window.KaishiGallerySettings.refresh()",null);}
    private void error(String text){if(!closed)web.evaluateJavascript("window.KaishiGallerySettings&&window.KaishiGallerySettings.status("+JSONObject.quote(text)+")",null);}
    private void stopUpload(){if(upload!=null){upload.close();upload=null;}if(!closed)web.evaluateJavascript("window.KaishiGallerySettings&&window.KaishiGallerySettings.uploadClosed()",null);}
    private void begin(){stopUpload();GalleryUpload next=new GalleryUpload(this,()->runOnUiThread(this::refresh));upload=next;new Thread(()->{try{String url=next.start();runOnUiThread(()->{if(closed||upload!=next){next.close();return;}getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);web.evaluateJavascript("window.KaishiGallerySettings.upload("+JSONObject.quote(url)+")",null);});}catch(Exception e){next.close();runOnUiThread(()->error("无法开启上传，请检查电视与手机的家庭网络"));}},"Kaishi-album-session").start();}
    protected void onResume(){super.onResume();if(web!=null){web.onResume();web.resumeTimers();web.evaluateJavascript("window.KaishiGallery&&window.KaishiGallery.active(true)",null);}}
    protected void onPause(){stopUpload();if(web!=null){web.evaluateJavascript("window.KaishiGallery&&window.KaishiGallery.active(false)",null);web.onPause();web.pauseTimers();}super.onPause();}
    public void onBackPressed(){web.evaluateJavascript("!!(window.KaishiGallery&&window.KaishiGallery.close())",value->{if(!"true".equals(value))finish();});}
    public boolean dispatchKeyEvent(KeyEvent event){int code=event.getKeyCode();if((code>=19&&code<=23||code==66)&&web!=null&&getWindow().getDecorView().hasWindowFocus()&&getCurrentFocus()==web){if(event.getAction()==KeyEvent.ACTION_DOWN)return onKeyDown(code,event);if(event.getAction()==KeyEvent.ACTION_UP)return onKeyUp(code,event);}return super.dispatchKeyEvent(event);}
    public boolean onKeyDown(int code,KeyEvent event){if(VoiceAssistant.systemVoiceKey(code))return super.onKeyDown(code,event);if(code==4){if(event.getRepeatCount()==0)onBackPressed();return true;}String key=code==19?"ArrowUp":code==20?"ArrowDown":code==21?"ArrowLeft":code==22?"ArrowRight":code==23||code==66?"Enter":null;if(key!=null){if(!key.equals("Enter")||event.getRepeatCount()==0)web.evaluateJavascript("window.KaishiGallerySettings&&window.KaishiGallerySettings.key("+JSONObject.quote(key)+")",null);return true;}return super.onKeyDown(code,event);}
    public boolean onKeyUp(int code,KeyEvent event){if(code>=19&&code<=23||code==66||code==4)return true;return super.onKeyUp(code,event);}
    protected void onDestroy(){closed=true;stopUpload();if(notice!=null)notice.dismiss();web.stopLoading();web.destroy();super.onDestroy();}
}
